#!/usr/bin/env bash
# run.sh - compare the speed of code generated by occ and a reference compiler.
#
#   tests/bench/run.sh [./occ]       (REF=clang to compare against clang)
#
# Every benchmark prints a checksum; all builds of a benchmark must agree.
set -u
cd "$(dirname "$0")/../.."
OCC="${1:-./occ}"
REF="${REF:-gcc}"
RUNS="${RUNS:-3}"
OUT=tests/out/bench
mkdir -p "$OUT"

configs=("occ -o none" "occ -o prod")
if command -v "$REF" >/dev/null; then
  configs+=("$REF -O0" "$REF -O2")
fi

build() { # config src exe
  case "$1" in
    "occ -o none") "$OCC" -q -o none -n "$3" "$2" ;;
    "occ -o prod") "$OCC" -q -o prod -n "$3" "$2" ;;
    *) $1 -std=c2x -w -o "$3" "$2" -lm ;;
  esac
}

best_time() { # exe -> seconds (best of RUNS)
  local best=""
  for ((r = 0; r < RUNS; r++)); do
    local start end t
    start=$(date +%s.%N)
    "$1" >/dev/null
    end=$(date +%s.%N)
    t=$(echo "$end - $start" | bc -l)
    if [[ -z "$best" ]] || (($(echo "$t < $best" | bc -l))); then best=$t; fi
  done
  printf "%.3f" "$best"
}

printf "%-12s" "benchmark"
for c in "${configs[@]}"; do printf " | %12s" "$c"; done
printf "\n%-12s" "------------"
for c in "${configs[@]}"; do printf " | %12s" "------------"; done
printf "\n"

status=0
for src in tests/bench/*.c; do
  name=$(basename "$src" .c)
  printf "%-12s" "$name"
  expected=""
  for c in "${configs[@]}"; do
    exe="$OUT/$name-$(echo "$c" | tr ' ' '_')"
    if ! build "$c" "$src" "$exe" 2>/dev/null; then
      printf " | %12s" "build error"
      status=1
      continue
    fi
    output=$("$exe")
    if [[ -z "$expected" ]]; then
      expected="$output"
    elif [[ "$output" != "$expected" ]]; then
      printf " | %12s" "WRONG"
      status=1
      continue
    fi
    printf " | %11ss" "$(best_time "$exe")"
  done
  printf "\n"
done
exit $status
